/**
 * DNN forward pass.
 * obs:    input array  [6]
 * output: output array [2]
 *
 * Note: clamp output to [-1, 1] before sending to motor driver.
 */
static inline void actor_forward(const float* obs, float* output) {
    float buf0[64];
    float buf1[64];
    const float* in  = obs;
    float*       out = buf0;

    // Layer 0: 6 -> 64, activation=tanh
    for (int o = 0; o < 64; o++) {
        float acc = layer0_bias[o];
        for (int j = 0; j < 6; j++)
            acc += layer0_weight[o * 6 + j] * in[j];
        out[o] = tanhf(acc);
    }
    in  = out;
    out = (out == buf0) ? buf1 : buf0;

    // Layer 1: 64 -> 64, activation=tanh
    for (int o = 0; o < 64; o++) {
        float acc = layer1_bias[o];
        for (int j = 0; j < 64; j++)
            acc += layer1_weight[o * 64 + j] * in[j];
        out[o] = tanhf(acc);
    }
    in  = out;
    out = (out == buf0) ? buf1 : buf0;

    // Layer 2: 64 -> 2, activation=none (output layer)
    for (int o = 0; o < 2; o++) {
        float acc = layer2_bias[o];
        for (int j = 0; j < 64; j++)
            acc += layer2_weight[o * 64 + j] * in[j];
        out[o] = acc;
    }
    for (int o = 0; o < 2; o++)
        output[o] = out[o];

}